module pulse_detect #(
    parameter s0 = 2'b00,
    parameter s1 = 2'b01,
    parameter s2 = 2'b10,
    parameter s3 = 2'b11
) (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= s0;
        data_out <= 0;
    end else begin
        case (state)
            s0: if (data_in == 1'b1) state <= s1;
                else state <= s0;
            s1: if (data_in == 1'b0) state <= s2;
                else state <= s1;
            s2: if (data_in == 1'b1) state <= s3;
                else state <= s2;
            s3: begin
                data_out <= 1;
                if (data_in == 1'b0) state <= s0;
                else state <= s3;
            end
        endcase
        if (state == s3) data_out <= 1;
        else data_out <= 0;
    end
end

endmodule
